const input = $input.first().json.body || $input.first().json;

const p1 = input.player1;
const p2 = input.player2;
const surface = input.surface || 'Hard';

const notes1 = (p1.notes || []).map(n => `- [${n.category}] ${n.content}`).join('\n');
const notes2 = (p2.notes || []).map(n => `- [${n.category}] ${n.content}`).join('\n');

const prompt = `You are a professional tennis analyst AI. Analyze this match and return ONLY valid JSON (no markdown, no code fences, no explanation outside the JSON).

MATCH: ${p1.name} (${p1.country_code}, ${p1.hand === 'L' ? 'Left' : 'Right'}-handed${p1.height_cm ? ', ' + p1.height_cm + 'cm' : ''}) vs ${p2.name} (${p2.country_code}, ${p2.hand === 'L' ? 'Left' : 'Right'}-handed${p2.height_cm ? ', ' + p2.height_cm + 'cm' : ''})
SURFACE: ${surface}

${p1.play_style ? 'PLAYER 1 STYLE: ' + p1.play_style : ''}
${(p1.strengths || []).length ? 'PLAYER 1 STRENGTHS: ' + p1.strengths.join(', ') : ''}
${(p1.weaknesses || []).length ? 'PLAYER 1 WEAKNESSES: ' + p1.weaknesses.join(', ') : ''}
${(p1.best_surfaces || []).length ? 'PLAYER 1 BEST SURFACES: ' + p1.best_surfaces.join(', ') : ''}

${p2.play_style ? 'PLAYER 2 STYLE: ' + p2.play_style : ''}
${(p2.strengths || []).length ? 'PLAYER 2 STRENGTHS: ' + p2.strengths.join(', ') : ''}
${(p2.weaknesses || []).length ? 'PLAYER 2 WEAKNESSES: ' + p2.weaknesses.join(', ') : ''}
${(p2.best_surfaces || []).length ? 'PLAYER 2 BEST SURFACES: ' + p2.best_surfaces.join(', ') : ''}

${notes1 ? 'PLAYER 1 NOTES:\n' + notes1 : ''}
${notes2 ? 'PLAYER 2 NOTES:\n' + notes2 : ''}

Return JSON exactly like this:
{
  "predicted_winner_id": "${p1.id}" or "${p2.id}",
  "confidence": 0.0 to 1.0,
  "reasoning": "2-3 sentence analysis of why this player is favored",
  "tactics_player1": "2-3 sentences on tactical approach for ${p1.name}",
  "tactics_player2": "2-3 sentences on tactical approach for ${p2.name}"
}`;

return [{ json: { prompt, player1_id: p1.id, player2_id: p2.id, surface, player1_name: p1.name, player2_name: p2.name } }];

const raw = $input.first().json.output || $input.first().json.text || JSON.stringify($input.first().json);

let parsed;
try {
  const jsonMatch = raw.match(/\{[\s\S]*\}/);
  if (jsonMatch) {
    parsed = JSON.parse(jsonMatch[0]);
  } else {
    parsed = {
      predicted_winner_id: $('Build Prompt').first().json.player1_id,
      confidence: 0.5,
      reasoning: raw,
      tactics_player1: '—',
      tactics_player2: '—'
    };
  }
} catch (e) {
  parsed = {
    predicted_winner_id: $('Build Prompt').first().json.player1_id,
    confidence: 0.5,
    reasoning: raw,
    tactics_player1: '—',
    tactics_player2: '—'
  };
}

return [{ json: parsed }];
